const url='https://rpc.flashbots.net/fast';
const from=26020642,to=26027794,pin='0x814f86238af7df00b7b5c05191d60da4de0f686d7cc72acf6351cd417315cb9e';
const address=['0x00000000000000adc04c56bf30ac9d3c0aaf14dc','0x0000000000000068f116a894984e2db1123eb395'];
const topic='0x9d9af8e38d66c62e2c12f0225249fd9d721c54b83f48d9352c97c6cacdcb6f31';
const collection='0x9c51a3cb5094b26aa1dcb380f3dc7e1a7c681c2d',weth='0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2';
const hex=n=>'0x'+n.toString(16);
async function rpc(method,params){const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('HTTP '+r.status);const b=await r.json();if(b.error)throw Error(JSON.stringify(b.error));return b.result}
if(Number(await rpc('eth_chainId',[]))!==1)throw Error('chain');
if((await rpc('eth_getBlockByNumber',[hex(to),false])).hash!==pin)throw Error('pin');
async function logs(a,b){try{const x=await rpc('eth_getLogs',[{address,topics:[topic],fromBlock:hex(a),toBlock:hex(b)}]);if(x.length>=10000)throw Error('possible cap');return x}catch(e){if(a===b)throw e;const m=Math.floor((a+b)/2);return [...await logs(a,m),...await logs(m+1,b)]}}
let floor=null;const seen=new Set();
const money=x=>x.t===0||(x.t===1&&x.token===weth);
for(let a=from;a<=to;a+=500)for(const l of await logs(a,Math.min(a+499,to))){
 if(l.removed)continue;const key=l.blockNumber+':'+l.logIndex;if(seen.has(key))continue;seen.add(key);
 const w=l.data.slice(2).match(/.{64}/g).map(x=>BigInt('0x'+x));
 const array=(i,s)=>{const o=Number(w[i]/32n);return Array.from({length:Number(w[o])},(_,j)=>{const k=o+1+j*s;return {t:Number(w[k]),token:'0x'+w[k+1].toString(16).padStart(40,'0'),amount:w[k+3]}})};
 const offer=array(2,4),c=array(3,5),nft=[...offer,...c].filter(x=>x.t>=2);
 if(offer.length!==1||nft.length!==1||nft[0].t!==2||nft[0].token!==collection||nft[0].amount!==1n)continue;
 let p;if(offer[0]===nft[0]&&c.length&&c.every(money))p=c.reduce((s,x)=>s+x.amount,0n);
 else if(money(offer[0])&&c.every(x=>x===nft[0]||money(x)))p=offer[0].amount;else continue;
 if(floor===null||p<floor)floor=p;
}
console.log((floor??0n).toString());

