const rpc=async(method,params)=>{const r=await fetch(a.recipe.source,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params})});if(!r.ok)throw Error('HTTP '+r.status);const j=await r.json();if(j.error)throw Error(JSON.stringify(j.error));return j.result;};
const hex=n=>'0x'+n.toString(16);
if(Number(await rpc('eth_chainId',[]))!==a.chainId)throw Error('chain');
if((await rpc('eth_getBlockByNumber',[hex(a.window.toBlock),false])).hash!==a.window.toBlockHash)throw Error('pin');
const addresses=['0x00000000000000adc04c56bf30ac9d3c0aaf14dc','0x0000000000000068f116a894984e2db1123eb395'];
const topic='0x9d9af8e38d66c62e2c12f0225249fd9d721c54b83f48d9352c97c6cacdcb6f31';
const collection='0x9c51a3cb5094b26aa1dcb380f3dc7e1a7c681c2d',weth='0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2';
