const pay=x=>x.t===0||(x.t===1&&x.token===weth);
const seen=new Set();let min=null,count=0;
for(let lo=a.window.fromBlock;lo<=a.window.toBlock;lo+=1000){
 for(const l of await logs(lo,Math.min(lo+999,a.window.toBlock))){
  const key=l.blockNumber+':'+l.logIndex;if(l.removed||seen.has(key))continue;seen.add(key);
  const d=l.data.slice(2),w=i=>BigInt('0x'+d.slice(i*64,i*64+64));
  const arr=(slot,stride)=>{const p=Number(w(slot))/32;return Array.from({length:Number(w(p))},(_,i)=>{const j=p+1+i*stride;return {t:Number(w(j)),token:'0x'+w(j+1).toString(16).padStart(40,'0'),amount:w(j+3)};});};
  const o=arr(2,4),c=arr(3,5),n=[...o,...c].filter(x=>x.t>=2);
  if(o.length!==1||n.length!==1||n[0].t!==2||n[0].token!==collection||n[0].amount!==1n)continue;
